<script setup lang="ts">import { onMounted, ref, watch } from 'vue';import { useRoute } from 'vue-router';import { api } from '../api';import type {Product} from '../stores';import ProductCard from '../components/ProductCard.vue';import {useCart,useSession} from '../stores';const route=useRoute(),products=ref<Product[]>([]),categories=ref<any[]>([]),loading=ref(false),error=ref(''),search=ref(String(route.query.search??'')),sort=ref('newest'),category=ref(String(route.query.category??''));async function load(){loading.value=true;try{const p=new URLSearchParams({limit:'24',sort:sort.value});if(search.value)p.set('search',search.value);if(category.value)p.set('category',category.value);products.value=(await api<{items:Product[]}>(`/products?${p}`)).items}catch(e:any){error.value=e.message}finally{loading.value=false}}const cart=useCart(),session=useSession();async function add(id:string){if(!session.user)return location.assign('/login');await cart.add(id)}onMounted(async()=>{categories.value=await api('/categories');load()});watch([search,sort,category],load);</script>
<template><main class="container page"><header class="page-title"><small>SHOPORA / CATALOG</small><h1>Thoughtful things, chosen well.</h1><p>Essential pieces for the way you live now.</p></header><div class="catalog"><aside class="filters"><label>Search<input v-model="search" placeholder="Search products"/></label><label>Category<select v-model="category"><option value="">All categories</option><option v-for="c in categories" :value="c.slug">{{c.name}}</option></select></label><label>Sort by<select v-model="sort"><option value="newest">Newest arrivals</option><option value="price_asc">Price: low to high</option><option value="price_desc">Price: high to low</option><option value="name">Name A–Z</option></select></label></aside><section><p class="count">{{loading?'Loading…':`${products.length} pieces found`}}</p><p v-if="error" class="notice">{{error}}</p><div class="products"><ProductCard v-for="p in products" :key="p.id" :product="p" @add="add"/></div><div v-if="!loading&&!products.length" class="empty">No pieces matched your selection.</div></section></div></main></template>
